<?php session_start(); if(!isset($_SESSION['user_id'])||strtolower($_SESSION['user_type']??'')!=='admin'){header('Location: ../login.php');exit;} ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Live Operations · MBUS</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css"><link rel="stylesheet" href="../Assets/css/bottom-nav.css"><link rel="stylesheet" href="../Assets/css/app-header.css"><style>body{font-family:Inter,system-ui;background:#f6f8fb;color:#162033;margin:0}.wrap{max-width:1100px;margin:auto;padding:1.25rem 1rem 7rem}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem}.card{background:#fff;border:1px solid #e5eaf1;border-radius:18px;padding:1rem;box-shadow:0 8px 24px #182b4b0d}.map{height:260px;border-radius:16px;background:linear-gradient(135deg,#dbeafe,#ecfeff);display:grid;place-items:center;color:#285f8f;margin-bottom:1rem}.metric{display:inline-flex;gap:.35rem;margin:.5rem .35rem .2rem 0;padding:.45rem .6rem;border-radius:999px;background:#f0f5fb;font-size:.86rem}.pickup{border-top:1px solid #edf1f5;padding:.65rem 0}.muted{color:#65748a}</style></head><body><main class="wrap"><h1><i class="fa fa-tower-broadcast"></i> Live operations</h1><p class="muted">Admin view · monitor every bus, onboard passengers, and pickup requests.</p><div id="map" class="map">Live operations map loading…</div><div id="buses" class="grid"></div></main><nav class="bottom-nav"><a href="admin_dashboard.php" class="bottom-nav-item"><i class="fa fa-home"></i><span>Home</span></a><a href="manage_schedules.php" class="bottom-nav-item"><i class="fa fa-calendar"></i><span>Schedules</span></a><a href="live_map.php" class="bottom-nav-item active"><i class="fa fa-map-location-dot"></i><span>Live</span></a><a href="manage_buses.php" class="bottom-nav-item"><i class="fa fa-bus"></i><span>Buses</span></a><a href="notifications.php" class="bottom-nav-item"><i class="fa fa-bell"></i><span>Alerts</span></a></nav><script>async function refresh(){const r=await fetch('../api/get_live_map_data.php',{cache:'no-store'});const j=await r.json();document.getElementById('map').innerHTML='<i class="fa fa-location-dot"></i> '+(j.buses?.length||0)+' live bus(es) · '+(j.pickups?.length||0)+' waiting request(s)';document.getElementById('buses').innerHTML=j.buses?.length?j.buses.map(b=>{const ps=(j.pickups||[]).filter(p=>String(p.bus_number)===String(b.bus_number));return `<article class="card"><h2>Bus ${b.bus_number}</h2><p class="muted">${b.origin||'No active route'} → ${b.destination||''}</p><span class="metric"><i class="fa fa-user-clock"></i>${b.waiting_count||0} waiting</span><span class="metric"><i class="fa fa-users"></i>${b.onboard_count||0} onboard</span><span class="metric"><i class="fa fa-signal"></i>${b.trip_status||'Live'}</span>${ps.length?'<h3>Waiting here</h3>'+ps.map(p=>`<div class="pickup"><strong>${p.full_name}</strong><br>${p.pickup_location}</div>`).join(''):''}</article>`}).join(''):'<article class="card"><p class="muted">No recent bus locations. Operators must allow location access and have an active trip.</p></article>';}refresh();setInterval(refresh,15000);</script></body></html>
